def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            component=[(r,c)]
            seen.add((r,c))
            for x,y in component:
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]==grid[r][c] and (a,b) not in seen:
                        seen.add((a,b)); component.append((a,b))
            if len(component)%3:
                for x,y in component: out[x][y]=0
    return out

